package com.familyguard.agent;
import static com.familyguard.agent.DetectionModels.*;import static org.junit.jupiter.api.Assertions.*;import java.nio.file.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;
class WebRestrictionTests{@TempDir Path temp;
 @Test void hostsConservaContenidoAjenoYEsReversible()throws Exception{Path hosts=temp.resolve("hosts");Files.writeString(hosts,"127.0.0.1 localhost\n");HostsFileFilter f=new HostsFileFilter(hosts);assertTrue(f.apply(Set.of("example.com")).successful());String blocked=Files.readString(hosts);assertTrue(blocked.contains("0.0.0.0 example.com"));assertTrue(blocked.contains("localhost"));assertTrue(f.apply(Set.of()).successful());assertFalse(Files.readString(hosts).contains(HostsFileFilter.BEGIN));assertTrue(Files.readString(hosts).contains("localhost"));}
 @Test void cacheDpapiSobreviveReinicio(){Path p=temp.resolve("web.bin");var s=new WebRestrictionStore(p);s.rules("America/Lima",List.of(rule(List.of())));byte[] raw=assertDoesNotThrow(()->Files.readAllBytes(p));assertFalse(new String(raw,java.nio.charset.StandardCharsets.ISO_8859_1).contains("example.com"));assertEquals(1,new WebRestrictionStore(p).snapshot().rules().size());}
 @Test void horarioBloqueaYFueraDeHorarioRestaura()throws Exception{Path hosts=temp.resolve("hosts");Files.writeString(hosts,"");var store=new WebRestrictionStore(temp.resolve("cache.bin"));var engine=new WebRestrictionEngine(store,new HostsFileFilter(hosts));var schedule=new WebSchedule(DayOfWeek.MONDAY,LocalTime.of(8,0),LocalTime.of(10,0),false,"BLOQUEAR");engine.replace("UTC",List.of(rule(List.of(schedule))));engine.apply(Instant.parse("2026-11-16T09:00:00Z"));assertTrue(Files.readString(hosts).contains("example.com"));engine.apply(Instant.parse("2026-11-16T11:00:00Z"));assertFalse(Files.readString(hosts).contains("example.com"));}
 @Test void temporalExpiradaNoBloquea()throws Exception{Path hosts=temp.resolve("hosts");Files.writeString(hosts,"");var store=new WebRestrictionStore(temp.resolve("cache.bin"));var engine=new WebRestrictionEngine(store,new HostsFileFilter(hosts));var r=new WebRule(1,"example.com",false,"BLOQUEAR",false,null,Instant.parse("2020-01-01T00:00:00Z"),1,List.of());store.rules("UTC",List.of(r));engine.apply(Instant.now());assertFalse(Files.readString(hosts).contains("example.com"));}
 @Test void modoPermitirBloqueaFueraDeVentana()throws Exception{Path hosts=temp.resolve("hosts");Files.writeString(hosts,"");var store=new WebRestrictionStore(temp.resolve("cache.bin"));var engine=new WebRestrictionEngine(store,new HostsFileFilter(hosts));var schedule=new WebSchedule(DayOfWeek.MONDAY,LocalTime.of(8,0),LocalTime.of(10,0),false,"PERMITIR");store.rules("UTC",List.of(new WebRule(1,"example.com",false,"PERMITIR",true,null,null,1,List.of(schedule))));engine.apply(Instant.parse("2026-11-16T11:00:00Z"));assertTrue(Files.readString(hosts).contains("example.com"));engine.apply(Instant.parse("2026-11-16T09:00:00Z"));assertFalse(Files.readString(hosts).contains("example.com"));}
 private WebRule rule(List<WebSchedule>s){return new WebRule(1,"example.com",true,"BLOQUEAR",true,null,null,1,s);}
}
